1	package numeric
2	
3	import (
4		"fmt"
5		"os"
6		"sync"
7		"sync/atomic"
8		"time"
9	)
10	
11	// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
12	type Clock interface {
13		Now() time.Time
14	}
15	
16	type wallClock struct{}
17	
18	func (wallClock) Now() time.Time { return time.Now().UTC() }
19	
20	// Option 配置 [Open] 的行为。
21	type Option func(*Store)
22	
23	// WithClock 注入自定义时钟。
24	func WithClock(c Clock) Option {
25		return func(s *Store) { s.now = c.Now }
26	}
27	
28	// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
29	//
30	// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
31	// idemIdentity 是幂等作用域（提交人, 请求号）的复合键。两个字段都按调用方
32	// 给出的完整字符串逐字节参与比较，允许包含 U+0000 与非法 UTF-8 字节
33	// （后者靠记录中的 identity_raw 兜底字段跨重开保真）。不能用分隔符把两个
34	// 字段拼成单个字符串：提交人 "a"、请求号 "b\x00c" 与提交人 "a\x00b"、
35	// 请求号 "c" 在任何分隔符方案下都会产生歧义（分隔符本身可以出现在字段内部）。
36	type idemIdentity struct {
37		submitter string
38		requestID string
39	}
40	
41	type Store struct {
42		dir string
43	
44		mu     sync.Mutex
45		jobs   []*storedJob // 严格按作业号（即提交先后）排列
46		byID   map[uint64]*storedJob
47		idem   map[idemIdentity]uint64 // (提交人, 请求号) -> 作业号
48		nextID uint64
49		closed bool
50	
51		now func() time.Time
52	
53		runningID uint64
54		waitCh    chan struct{}
55		stopCh    chan struct{}
56		stopping  atomic.Bool
57		wg        sync.WaitGroup
58	
59		// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
60		// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
61		// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
62		compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)
63	
64		// persistFault 仅用于包内确定性测试：若非 nil，每次 persist 都会先调用它，
65		// 返回非 nil 即模拟该次记录保存失败（如同临时记录无法创建或原记录无法替换）。
66		// 生产代码恒为 nil。钩子可按作业号与“待保存的当前状态”只让某一次写入失败
67		// （例如仅让成功归档写入失败），而让其余记录照常落盘。
68		persistFault func(j *storedJob) error
69	}
70	
71	// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
72	//
73	// 恢复语义：
74	//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
75	//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
76	//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
77	//   - 成功状态始终与完整归档同时可见。
78	func Open(dir string, opts ...Option) (*Store, error) {
79		if err := os.MkdirAll(dir, 0o700); err != nil {
80			return nil, err
81		}
82		jobs, maxID, err := loadDir(dir)
83		if err != nil {
84			return nil, err
85		}
86		s := &Store{
87			dir:    dir,
88			jobs:   jobs,
89			byID:   make(map[uint64]*storedJob),
90			idem:   make(map[idemIdentity]uint64),
91			nextID: maxID + 1,
92			now:    wallClock{}.Now,
93			waitCh: make(chan struct{}, 1),
94			stopCh: make(chan struct{}),
95		}
96		for _, opt := range opts {
97			opt(s)
98		}
99		for _, j := range jobs {
100			s.byID[j.id] = j
101			if j.requestID != "" {
102				s.idem[idemIdentity{j.submitter, j.requestID}] = j.id
103			}
104		}
105		// 重建失败/取消作业对排队下游的阻断。
106		s.cascadeLocked()
107		s.wg.Add(1)
108		go s.worker()
109		return s, nil
110	}
111	
112	// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
113	// 排队作业原样保留在磁盘上，下次 [Open] 继续。
114	//
115	// 多次 Close（含并发调用）共同完成对同一个归档对象的一次关闭：每个调用都
116	// 等到 worker 退出、运行中作业的中断处理已经落盘后才成功返回。后发调用
117	// 不能只因为前一次调用已把关闭标记置位就提前返回——否则调用方可能据此立即
118	// 重新打开目录，而旧 worker 仍在补写运行作业的结果。归档完全关闭后的再次
119	// Close 立即成功返回；空闲归档（无运行中作业）也直接完成关闭。
120	func (s *Store) Close() error {
121		s.mu.Lock()
122		if s.closed {
123			// 关闭可能正由另一次并发 Close 进行。wg 在 Open 时 +1、worker 退出
124			// 时归零；Wait 允许被多个 goroutine 同时等待，所有调用都在同一次
125			// 关闭真正完成（worker 已退出、再无计算与补写）时才返回。
126			// 已完全关闭时计数早已归零，这里立即成功返回。
127			s.mu.Unlock()
128			s.wg.Wait()
129			return nil
130		}
131		s.closed = true
132		var running *storedJob
133		if s.runningID != 0 {
134			running = s.byID[s.runningID]
135		}
136		s.mu.Unlock()
137	
138		if s.stopping.CompareAndSwap(false, true) {
139			close(s.stopCh)
140		}
141		// 中止正在运行的计算。
142		if running != nil {
143			running.canceled.Store(true)
144		}
145		s.notify()
146		s.wg.Wait()
147		return nil
148	}
149	
150	// Submit 接受一次作业提交。
151	//
152	// 空序列返回 [ErrEmptySequence]；依赖列表结构不合法（单依赖与列表同时启用、
153	// 含零或重复作业号）返回 [ErrInvalidDependency]——这些请求本身的格式错误先于
154	// 幂等判定拒绝，即使复用已接受的请求号也不例外。
155	//
156	// 非空请求号命中同一提交人的已接受请求时，幂等判定先于“引用的上游必须存在”
157	// 校验：内容（整数序列及次序、种子、有序依赖内容）完全一致时返回原作业的
158	// 当前详情且不返回错误，即使其直接上游记录在重开归档后已缺失、原作业已因此
159	// 被改判为失败；内容不一致返回 [ErrIdempotencyConflict]（同时返回原作业视图，
160	// 仍引用缺失上游时在原因中一并指出），原记录保持原样。重复提交不创建新作业、
161	// 不补建缺失上游、不重新排队失败作业、也不改写原始参数或失败记录。
162	//
163	// 未命中已接受请求的新请求（提交人不同、请求号不同或请求号为空）引用不存在
164	// 的依赖时返回 [ErrDependencyNotFound]；上述拒绝都不产生记录，也不占用请求号。
165	// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
166	func (s *Store) Submit(req SubmitRequest) (*Job, error) {
167		s.mu.Lock()
168		defer s.mu.Unlock()
169		if s.closed || s.stopping.Load() {
170			return nil, ErrStoreClosed
171		}
172		if len(req.Values) == 0 {
173			return nil, ErrEmptySequence
174		}
175		// 先校验与上游存在性无关的列表结构（单依赖与列表互斥、零与重复作业号），
176		// 这类拒绝不依赖内存索引，对新请求与幂等重放一视同仁。
177		if err := s.validateDependencyShapeLocked(&req); err != nil {
178			return nil, err
179		}
180		deps := requestDeps(&req)
181		if req.RequestID != "" {
182			key := idemIdentity{req.Submitter, req.RequestID}
183			if origID, ok := s.idem[key]; ok {
184				orig := s.byID[origID]
185				// 幂等重放先于“引用的上游必须存在”的校验：重新打开归档后原作业
186				// 直接上游的记录可能已经缺失，原作业也因此被改判为失败并落盘。
187				// 只要本次提交的整数序列及次序、种子与有序依赖内容和已接受请求
188				// 完全一致（单依赖写法与只含同一作业号的列表等价），就返回原作业
189				// 的当前详情——不重建缺失上游、不重新排队、不补算、不改写记录。
190				if sameContent(orig, &req) {
191					return s.viewLocked(orig), nil
192				}
193				return s.viewLocked(orig),
194					fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d，且本次内容与原请求不一致%s，原记录保持原样",
195						ErrIdempotencyConflict, req.Submitter, req.RequestID, origID,
196						s.missingDependencyNoteLocked(deps))
197			}
198		}
199		// 新请求（请求号为空，或该提交人首次使用此请求号）仍要求每个直接上游
200		// 都存在；引用不存在上游的提交被拒绝，不产生记录，也不占用请求号。
201		// 此检查必须位于幂等判定之后：上面的重放/冲突分支可能引用缺失的上游。
202		if err := s.validateDependenciesExistLocked(deps); err != nil {
203			return nil, err
204		}
205	
206		now := s.now().UTC()
207		j := &storedJob{
208			id:           s.nextID,
209			submitter:    req.Submitter,
210			requestID:    req.RequestID,
211			seed:         req.Seed,
212			values:       append([]int64(nil), req.Values...),
213			dependencies: append([]uint64(nil), deps...),
214			queuedAt:     now,
215			status:       StatusQueued,
216		}
217		// 先持久化，接受之后该提交即不可丢失。
218		if err := s.persist(j); err != nil {
219			return nil, err
220		}
221		s.nextID++
222		s.jobs = append(s.jobs, j)
223		s.byID[j.id] = j
224		if req.RequestID != "" {
225			s.idem[idemIdentity{req.Submitter, req.RequestID}] = j.id
226		}
227		// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
228		s.cascadeLocked()
229		s.notifyLocked()
230		return s.viewLocked(j), nil
231	}
232	
233	// requestDeps 规范化一次提交的直接上游作业号列表：
234	// 非空 Dependencies 优先（保持次序）；否则单依赖方式退化为只含一个作业号的列表；
235	// 两者皆无则为 nil。调用前须先经 [Store.validateDependencyShapeLocked] 与
236	// （新请求路径上的）[Store.validateDependenciesExistLocked] 校验。
237	func requestDeps(req *SubmitRequest) []uint64 {
238		if len(req.Dependencies) > 0 {
239			return append([]uint64(nil), req.Dependencies...)
240		}
241		if req.HasDependency {
242			return []uint64{req.DependencyID}
243		}
244		return nil
245	}
246	
247	// validateDependencyShapeLocked 在持锁状态下校验提交依赖列表中与上游存在性
248	// 无关的结构问题：
249	//   - 单依赖方式与非空列表同时启用 → 拒绝；
250	//   - 列表含零或重复作业号 → 拒绝（错误指出具体作业号）。
251	//
252	// 该校验先于幂等判定执行：空整数序列、依赖号为零、重复依赖与两种写法
253	// 同时启用都属于请求本身的格式错误，即使提交人+请求号与已接受请求相同
254	// 也仍返回原有的对应拒绝。
255	func (s *Store) validateDependencyShapeLocked(req *SubmitRequest) error {
256		if req.HasDependency && len(req.Dependencies) > 0 {
257			return fmt.Errorf("%w：单依赖方式与依赖列表不能同时启用", ErrInvalidDependency)
258		}
259		deps := requestDeps(req)
260		seen := make(map[uint64]struct{}, len(deps))
261		for _, id := range deps {
262			if id == 0 {
263				return fmt.Errorf("%w：依赖列表包含无效作业号 0", ErrInvalidDependency)
264			}
265			if _, dup := seen[id]; dup {
266				return fmt.Errorf("%w：依赖列表包含重复作业号 %d", ErrInvalidDependency, id)
267			}
268			seen[id] = struct{}{}
269		}
270		return nil
271	}
272	
273	// validateDependenciesExistLocked 校验规范化后的依赖列表只引用当前归档中
274	// 存在的作业。仅适用于幂等判定之后的新请求：已接受请求的重放（或内容
275	// 冲突）即使引用了重开后缺失的上游，也要返回原作业而不是被这里拒绝。
276	//
277	// 任一拒绝都不产生记录，也不占用幂等请求号。
278	func (s *Store) validateDependenciesExistLocked(deps []uint64) error {
279		for _, id := range deps {
280			if s.byID[id] == nil {
281				return fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, id)
282			}
283		}
284		return nil
285	}
286	
287	// missingDependencyNoteLocked 在幂等冲突时补充说明：若本次（与原请求内容
288	// 不一致的）提交仍引用已经缺失的上游，明确指出缺失的作业号，使冲突原因
289	// 不会被误读成仅仅是上游不存在。
290	func (s *Store) missingDependencyNoteLocked(deps []uint64) string {
291		for _, id := range deps {
292			if s.byID[id] == nil {
293				return fmt.Sprintf("；本次引用的直接上游作业 %d 记录已缺失", id)
294			}
295		}
296		return ""
297	}
298	
299	// sameContent 判断两次提交的内容是否一致；整数次序或依赖列表（内容与次序）
300	// 不同即视为不同内容。单依赖方式与只含同一作业号的列表视为相同内容。
301	func sameContent(j *storedJob, req *SubmitRequest) bool {
302		if j.seed != req.Seed {
303			return false
304		}
305		rd := requestDeps(req)
306		if len(j.dependencies) != len(rd) {
307			return false
308		}
309		for i := range j.dependencies {
310			if j.dependencies[i] != rd[i] {
311				return false
312			}
313		}
314		if len(j.values) != len(req.Values) {
315			return false
316		}
317		for i := range j.values {
318			if j.values[i] != req.Values[i] {
319				return false
320			}
321		}
322		return true
323	}
324	
325	// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
326	func (s *Store) Get(id uint64) (*Job, error) {
327		s.mu.Lock()
328		defer s.mu.Unlock()
329		j := s.byID[id]
330		if j == nil {
331			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
332		}
333		return s.viewLocked(j), nil
334	}
335	
336	// Cancel 请求取消作业。
337	//
338	// 排队或运行中的作业都可以取消；取消以“取消状态已成功保存进归档记录”为生效
339	// 条件：只有原子替换原记录成功后，返回结果、可查询状态与磁盘记录才一致地呈现
340	// 为取消，该作业及依赖它的作业才不会再产生成功归档。若取消记录无法创建临时
341	// 文件或无法替换原记录，返回的是实际保存错误，作业保持原状——不新增完成时间、
342	// 不清空原有信息、不中止正在运行的计算、不级联标记下游，排队与调度规则不变；
343	// 写入条件恢复后对仍处于排队或运行状态的同一作业再次取消会重新尝试保存。
344	// 重复取消已取消的作业仍返回成功；对已成功或已失败的作业取消返回
345	// [ErrNotCancellable]，原结果保持不变（计算在两次取消请求之间完成时亦然）。
346	func (s *Store) Cancel(id uint64) (*Job, error) {
347		s.mu.Lock()
348		defer s.mu.Unlock()
349		if s.closed {
350			return nil, ErrStoreClosed
351		}
352		j := s.byID[id]
353		if j == nil {
354			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
355		}
356		switch j.status {
357		case StatusCanceled:
358			return s.viewLocked(j), nil
359		case StatusSucceeded, StatusFailed:
360			return s.viewLocked(j),
361				fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
362		}
363	
364		// queued / running：先把取消终态写入原记录，确认原子替换成功后才让取消
365		// 生效。持锁期间外界观察不到中间态；若创建临时记录或替换原记录失败，
366		// 必须逐字段回滚，内存与磁盘都保持取消前的原状并返回实际保存错误，
367		// 不能把这次取消当作已完成。
368		now := s.now().UTC()
369		prevStatus := j.status
370		prevFinishedAt := j.finishedAt
371		prevReason := j.failureReason
372		prevBlocker := j.blockerID
373		prevEffective := j.effectiveValues
374		prevArchive := j.archive
375		j.status = StatusCanceled
376		j.failureReason = ""
377		j.blockerID = 0
378		if j.finishedAt.IsZero() {
379			j.finishedAt = now
380		}
381		j.effectiveValues = nil
382		j.archive = nil
383		if err := s.persist(j); err != nil {
384			j.status = prevStatus
385			j.finishedAt = prevFinishedAt
386			j.failureReason = prevReason
387			j.blockerID = prevBlocker
388			j.effectiveValues = prevEffective
389			j.archive = prevArchive
390			return nil, err
391		}
392	
393		// 取消已确认保存：提交终态，让正在运行的计算尽快中止，并级联标记下游。
394		j.canceled.Store(true)
395		// 依赖它的等待者一并失败，且继续向更下游传播。
396		s.cascadeLocked()
397		s.notifyLocked()
398		return s.viewLocked(j), nil
399	}
400	
401	// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
402	// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
403	func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
404		s.mu.Lock()
405		defer s.mu.Unlock()
406		if !start.IsZero() && !end.IsZero() && start.After(end) {
407			return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
408				ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
409		}
410		out := make([]*Job, 0)
411		for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
412			if j.submitter != submitter {
413				continue
414			}
415			if !start.IsZero() && j.queuedAt.Before(start) {
416				continue
417			}
418			if !end.IsZero() && j.queuedAt.After(end) {
419				continue
420			}
421			out = append(out, s.viewLocked(j))
422		}
423		return out, nil
424	}
425	
426	// cascadeLocked 把“直接上游已失败/取消”的排队作业标记为失败并递归传播。
427	//
428	// 上游在提交时必须已存在，因此上游作业号必然更小，按作业号升序单趟
429	// 扫描即可让阻断沿链条传播到最下游。选择直接阻断者、确定根因与构造失败
430	// 原因统一走 blocker.go 中的规则（与重开归档同一套）：作业有多个直接上游时
431	// 按保存的依赖顺序选取最靠前的已失败/取消者，根因沿该上游已有的阻断信息
432	// 保留；作业一旦失败，其原因不再被后来发生的上游状态变化改写。
433	func (s *Store) cascadeLocked() {
434		for _, j := range s.jobs {
435			if j.status != StatusQueued || len(j.dependencies) == 0 {
436				continue
437			}
438			directID, direct, blocked := pickBlockingUpstream(j, s.byID, runtimeUpstreamBlocked)
439			if !blocked {
440				continue
441			}
442			root := blockerRoot(direct, directID)
443			s.markFailedLocked(j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
444		}
445	}
446	
447	// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
448	// 可运行要求全部直接上游都已成功并归档；只要还有一个上游在排队或运行，
449	// 该作业就被跳过，不挡住后面可运行的作业。
450	func (s *Store) pickRunnableLocked() *storedJob {
451		for _, j := range s.jobs {
452			if j.status != StatusQueued {
453				continue
454			}
455			if len(j.dependencies) == 0 {
456				return j
457			}
458			ready := true
459			for _, id := range j.dependencies {
460				dep := s.byID[id]
461				if dep == nil || dep.status != StatusSucceeded {
462					ready = false
463					break
464				}
465			}
466			if ready {
467				return j
468			}
469		}
470		return nil
471	}
472	
473	// notifyLocked 在持锁状态下非阻塞唤醒 worker。
474	func (s *Store) notifyLocked() {
475		select {
476		case s.waitCh <- struct{}{}:
477		default:
478		}
479	}
480	
481	// notify 在不持锁时唤醒 worker。
482	func (s *Store) notify() {
483		s.mu.Lock()
484		s.notifyLocked()
485		s.mu.Unlock()
486	}
487	
488	// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
489	func (s *Store) persistRetry(j *storedJob, attempts int) error {
490		var err error
491		for i := 0; i < attempts; i++ {
492			if err = s.persist(j); err == nil {
493				return nil
494			}
495		}
496		return err
497	}
498	
499	// worker 是本地唯一的计算执行体。
500	func (s *Store) worker() {
501		defer s.wg.Done()
502		for {
503			s.mu.Lock()
504			if s.stopping.Load() {
505				s.mu.Unlock()
506				return
507			}
508			j := s.pickRunnableLocked()
509			if j == nil {
510				ch := s.waitCh
511				s.mu.Unlock()
512				select {
513				case <-ch:
514				case <-s.stopCh:
515				}
516				continue
517			}
518	
519			// 进入运行并原子持久化该状态。
520			j.status = StatusRunning
521			j.startedAt = s.now().UTC()
522			// 实际输入 = 原始序列 + 各直接上游的总和（严格按列表顺序追加）。
523			inputs := append([]int64(nil), j.values...)
524			for _, id := range j.dependencies {
525				if dep := s.byID[id]; dep != nil && dep.archive != nil {
526					inputs = append(inputs, dep.archive.Sum)
527				}
528			}
529			seed := j.seed
530			s.runningID = j.id
531			if err := s.persistRetry(j, 3); err != nil {
532				// 连运行状态都无法落盘：保守地失败，不进行计算。
533				s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
534				s.runningID = 0
535				s.cascadeLocked()
536				s.notifyLocked()
537				s.mu.Unlock()
538				continue
539			}
540			s.mu.Unlock()
541	
542			abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
543			doCompute := s.compute
544			if doCompute == nil {
545				doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
546					return computeResult(in, sd, c)
547				}
548			}
549			sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)
550	
551			s.mu.Lock()
552			s.runningID = 0
553			switch {
554			case j.status == StatusCanceled:
555				// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
556				j.archive = nil
557				j.effectiveValues = nil
558				_ = s.persistRetry(j, 3)
559				s.cascadeLocked()
560			case s.stopping.Load():
561				s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
562				s.cascadeLocked()
563			case !ok:
564				s.markFailedLocked(j, reason, 0)
565				s.cascadeLocked()
566			default:
567				// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
568				completed := s.now().UTC()
569				a := newArchive(j, inputs, sum, sumSq, completed)
570				j.effectiveValues = append([]int64(nil), inputs...)
571				j.status = StatusSucceeded
572				j.finishedAt = completed
573				j.failureReason = ""
574				j.blockerID = 0
575				j.archive = a
576				if err := s.persistRetry(j, 3); err != nil {
577					// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
578					j.archive = nil
579					j.effectiveValues = nil
580					s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
581					// 归档写入失败与计算溢出等失败同等对待：立即沿依赖链阻断所有仍在
582					// 排队等待它的作业，使等待者无需等到下一次提交/取消即进入失败终态。
583					s.cascadeLocked()
584				}
585			}
586			s.notifyLocked()
587			s.mu.Unlock()
588		}
589	}
590	
591	// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
592	func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
593		j.status = StatusFailed
594		j.failureReason = reason
595		j.blockerID = blocker
596		if j.finishedAt.IsZero() {
597			j.finishedAt = s.now().UTC()
598		}
599		j.archive = nil
600		j.effectiveValues = nil
601		_ = s.persistRetry(j, 3)
602	}
603	
604	// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
605	// 上游作业号只作记录，不参与任何摘要与校验值。
606	func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
607		inDigest := inputsDigestHex(effective, j.seed)
608		resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
609		log := buildLog(effective, j.seed, sum, sumSquares)
610		checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
611		var firstDep uint64
612		if len(j.dependencies) > 0 {
613			firstDep = j.dependencies[0]
614		}
615		return &Archive{
616			JobID:           j.id,
617			Submitter:       j.submitter,
618			RequestID:       j.requestID,
619			IdentityRaw:     rawIdentity(j.submitter, j.requestID),
620			Seed:            j.seed,
621			Values:          append([]int64(nil), j.values...),
622			HasDependency:   len(j.dependencies) > 0,
623			DependencyID:    firstDep,
624			Dependencies:    append([]uint64(nil), j.dependencies...),
625			EffectiveValues: append([]int64(nil), effective...),
626			InputsDigest:    inDigest,
627			Sum:             sum,
628			SumOfSquares:    sumSquares,
629			ResultDigest:    resDigest,
630			Log:             log,
631			Checksum:        checksum,
632			CompletedAt:     completedAt,
633		}
634	}
635	
636	// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
637	func (s *Store) viewLocked(j *storedJob) *Job {
638		v := &Job{
639			ID:              j.id,
640			Submitter:       j.submitter,
641			RequestID:       j.requestID,
642			Seed:            j.seed,
643			Values:          append([]int64(nil), j.values...),
644			Dependencies:    append([]uint64(nil), j.dependencies...),
645			QueuedAt:        j.queuedAt,
646			StartedAt:       j.startedAt,
647			FinishedAt:      j.finishedAt,
648			Status:          j.status,
649			FailureReason:   j.failureReason,
650			BlockerID:       j.blockerID,
651			EffectiveValues: append([]int64(nil), j.effectiveValues...),
652		}
653		v.HasDependency = len(j.dependencies) > 0
654		if len(j.dependencies) > 0 {
655			v.DependencyID = j.dependencies[0]
656		}
657		if j.status == StatusQueued {
658			v.WaitReason = WaitSlot
659			// 列出尚未成功归档的直接上游，保持提交时的顺序。
660			for _, id := range j.dependencies {
661				if dep := s.byID[id]; dep == nil || dep.status != StatusSucceeded {
662					v.PendingDependencies = append(v.PendingDependencies, id)
663				}
664			}
665			if len(v.PendingDependencies) > 0 {
666				v.WaitReason = WaitDependency
667			}
668		}
669		if j.archive != nil {
670			a := *j.archive
671			a.Values = append([]int64(nil), j.archive.Values...)
672			a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
673			a.Dependencies = append([]uint64(nil), j.archive.Dependencies...)
674			if j.archive.IdentityRaw != nil {
675				raw := *j.archive.IdentityRaw
676				a.IdentityRaw = &raw
677			}
678			v.Archive = &a
679		}
680		return v
681	}
682	
683	// Dir 返回归档目录路径。
684	func (s *Store) Dir() string { return s.dir }
685

